llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Codeine, the closest structural analogue sharing the methoxy-morphinan scaffold, has absolute oral bioavailability of 42–71% in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Codeine phosphate oral bioavailability was estimated as ~100% based on urinary recovery, indicating extensive absorption and high systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Absolute oral bioavailability of codeine in postoperative patients was 40%, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Codeine oral F was 0.50 in humans, consistent with moderate-to-high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Codeine sulfate oral bioavailability in healthy subjects was 80.5%, supporting high F for the closely related query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ethylmorphine, an N-ethyl codeine analogue, had median systemic availability 0.74 (range 0.54–0.92), supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Morphine, the demethylated analogue, had absolute oral bioavailability 37.2% (30.1–44.3), above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Noscapine, another morphinan alkaloid, had absolute oral bioavailability of 30%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Pethidine, a synthetic opioid with similar basic amine and lipophilic features, had absolute F of 0.57, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "One slow-acting oral morphine formulation gave systemic availability of 18.3%, just below the threshold, but this is formulation-specific and structurally less transferable than codeine data.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a codeine-like morphinan; the closest analogue codeine has absolute oral bioavailability of 40–71%, and other morphinan/opioid analogues (ethylmorphine, morphine, noscapine, pethidine) are mostly ≥30%, so F ≥20% is strongly supported. One low morphine formulation value (18.3%) is outweighed by higher-transfer supportive evidence.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the exact query stereoisomer.",
    "Codeine F values vary widely across studies, though most are above the 20% threshold.",
    "No human PK data for the specific C6 stereochemistry/regiochemistry of the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

